<?php namespace App\Domains\Coupon\Models; use Illuminate\Database\Eloquent\Model; class Coupon extends Model { protected $fillable = [ 'code', 'type', 'value', 'min_amount', 'uses_left', 'expires_at', 'is_active', ]; protected $casts = [ 'value' => 'decimal:2', 'min_amount' => 'decimal:2', 'expires_at' => 'datetime', 'is_active' => 'boolean', ]; public function isValid(float $cartTotal): bool { if (!$this->is_active) return false; if ($this->expires_at && $this->expires_at->isPast()) return false; if ($this->uses_left !== null && $this->uses_left <= 0) return false; if ($cartTotal < $this->min_amount) return false; return true; } public function calculateDiscount(float $subtotal): float { if ($this->type === 'percentage') { return round($subtotal * ($this->value / 100), 2); } return min($this->value, $subtotal); } }